  async function answer(){if(!activeQuestion||!choice)return;const questionId=activeQuestion.id;setPinnedQuestionIds(prev=>prev.includes(questionId)?prev:[...prev,questionId]);setAppliedQuestionIds(prev=>{const base=prev??visible.map((q:Row)=>q.id);return base.includes(questionId)?base:[...prev??visible.map((q:Row)=>q.id),questionId];});const requestId=crypto.randomUUID();const res=await api("/rest/v1/rpc/submit_answer",token,{method:"POST",body:JSON.stringify({p_question_id:questionId,p_selected_key:choice,p_request_id:requestId})});setResult(res);setAttempts(prev=>[{question_id:questionId,student_id:user?.id,is_correct:!!res?.is_correct,created_at:new Date().toISOString()},...prev.filter(a=>!(a.question_id===questionId&&a.student_id===user?.id))]);}
  const candidates=useMemo(()=>questions.filter(q=>(disciplineIds.length===0||disciplineIds.includes(q.discipline_id))&&(subjectIds.length===0||subjectIds.includes(q.subject_id))&&(modality==="all"||q.modality===modality)&&(status==="all"||(status==="unanswered"?!attempts.some(a=>a.question_id===q.id&&a.student_id===user?.id):status==="answered"?attempts.some(a=>a.question_id===q.id&&a.student_id===user?.id):status==="correct"?attempts.find(a=>a.question_id===q.id&&a.student_id===user?.id)?.is_correct===true:attempts.find(a=>a.question_id===q.id&&a.student_id===user?.id)?.is_correct===false))),[questions,disciplineIds,subjectIds,modality,status,attempts,user?.id]);
  const visible=useMemo(()=>{const ids=appliedQuestionIds===null?null:new Set([...appliedQuestionIds,...pinnedQuestionIds,...(activeQuestion?[activeQuestion.id]:[])]);return questions.filter(q=>(ids===null?candidates.some(c=>c.id===q.id)||!!(activeQuestion&&activeQuestion.id===q.id):ids.has(q.id))&&(disciplineIds.length===0||disciplineIds.includes(q.discipline_id))&&(subjectIds.length===0||subjectIds.includes(q.subject_id))&&(modality==="all"||q.modality===modality));},[questions,candidates,appliedQuestionIds,pinnedQuestionIds,disciplineIds,subjectIds,modality,activeQuestion]);
  const pageSize=20; const totalPages=Math.max(1,Math.ceil(visible.length/pageSize)); const pagedQuestions=visible.slice((currentPage-1)*pageSize,currentPage*pageSize);
