  const latest=attempts.filter(a=>a.student_id===user?.id); const total=latest.length; const correct=latest.filter(a=>a.is_correct===true).length;
  const statsStart=period==="custom"?new Date(customStart+"T00:00:00"):period==="all"?new Date("2000-01-01T00:00:00"):new Date(Date.now()-(Number(period)-1)*86400000); const statsEnd=period==="custom"?new Date(customEnd+"T23:59:59"):new Date();
  const periodAttempts=latest.filter(a=>{const d=new Date(a.created_at);return !Number.isNaN(d.getTime())&&d>=statsStart&&d<=statsEnd;});
