  const bySubject=Object.values(periodAttempts.reduce((acc:Record<string,any>,a:Row)=>{const q=questionById.get(a.question_id);const key=q?.subject_id||"unknown";const label=subjects.find(x=>x.id===key)?.name||(key==="unknown"?"Assunto não catalogado":"Assunto");acc[key]??={name:label,discipline:disciplines.find(d=>d.id===q?.discipline_id)?.name||"",total:0,correct:0,wrong:0};acc[key].total++;if(a.is_correct===true)acc[key].correct++;else if(a.is_correct===false)acc[key].wrong++;return acc;},{})).map((x:any)=>({...x,accuracy:x.total?Math.round(x.correct/x.total*100):0})).sort((a:any,b:any)=>b.wrong-a.wrong);
